agent-browser eval "(() => {
  const paths = Array.from(document.querySelectorAll('path[aria-label]'));
  const speciesColors = {};
  paths.forEach(p => {
    const label = p.getAttribute('aria-label') || '';
    const match = label.match(/Species:\s*([^;]+)/);
    if (match) {
      const species = match[1].trim();
      const stroke = p.getAttribute('stroke');
      const fill = p.getAttribute('fill');
      if (!speciesColors[species]) {
        speciesColors[species] = new Set();
      }
      speciesColors[species].add(JSON.stringify({ stroke, fill }));
    }
  });
  const result = {};
  for (const species in speciesColors) {
    result[species] = Array.from(speciesColors[species]).map(s => JSON.parse(s));
  }
  return result;
})()"

agent-browser eval "(() => {
  const panels = [
    'child__row_Body_Mass__g_column_Beak_Length__mm__group',
    'child__row_Body_Mass__g_column_Beak_Depth__mm__group',
    'child__row_Flipper_Length__mm_column_Beak_Length__mm__group',
    'child__row_Flipper_Length__mm_column_Beak_Depth__mm__group'
  ];
  const panelColors = {};
  panels.forEach(panelClass => {
    const panelEl = document.querySelector('.' + panelClass);
    if (!panelEl) {
      panelColors[panelClass] = 'not found';
      return;
    }
    const paths = Array.from(panelEl.querySelectorAll('path[aria-label]'));
    const colors = new Set();
    paths.forEach(p => {
      colors.add(p.getAttribute('stroke'));
    });
    panelColors[panelClass] = Array.from(colors);
  });
  return panelColors;
})()"

agent-browser eval "(() => {
  const legends = Array.from(document.querySelectorAll('.role-legend'));
  return legends.map(el => {
    const titleEl = el.querySelector('.role-legend-title text');
    const title = titleEl ? titleEl.textContent : 'no title';
    const labels = Array.from(el.querySelectorAll('.role-legend-label text')).map(l => l.textContent);
    return { title, labels };
  });
})()"

agent-browser eval "(() => {
  const elements = Array.from(document.querySelectorAll('*'));
  const legendLabels = [];
  elements.forEach(el => {
    const label = el.getAttribute('aria-label') || '';
    if (label.toLowerCase().includes('legend')) {
      legendLabels.push({
        tagName: el.tagName,
        className: el.getAttribute('class'),
        ariaLabel: label
      });
    }
  });
  return legendLabels;
})()"

